94	// elf_engine_arch_error (the ELF-vs-engine width guard shared with profile)
95	// lives in engine_registry.hpp, next to resolve_accurate_engine.
96	
97	// print_dry_run (the shared --dry-run preview) lives in argv.hpp, next to
98	// render_argv.
