291	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
292	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
293	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
294	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
295	  const char* iceman = std::getenv("ICEMAN");
296	  if (!iceman || !*iceman) {
297	    std::fprintf(stderr,
298	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
299	                 "(export ICEMAN=<path to ICEman binary>)\n");
300	    return 2;
301	  }
302	  // Build vsim argv from the standalone template, appending user passthrough
303	  // and the JTAG port flag.
304	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
305	  if (elf.empty()) return 2;
306	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
307	  std::vector<std::string> vsim_pass = cli.passthrough;
308	  vsim_pass.push_back("--jtag-port");
309	  vsim_pass.push_back(jtag_port);
310	  std::string err;
311	  const std::vector<std::string> vsim_argv =
312	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
313	  if (!err.empty()) {
314	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
315	    return 2;
316	  }
317	  std::fprintf(stderr,
318	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
319	               jtag_port.c_str());
320	  if (fork_background(vsim_argv) < 0) {
321	    std::fprintf(stderr,
322	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
323	    return 1;
324	  }
325	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
326	  // Wait for the port to be LISTENing before launching the debugger (it does not
327	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
328	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
329	  // but launch anyway if it never appears.
330	  if (const int pnum = std::atoi(jtag_port.c_str());
331	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
332	    std::fprintf(stderr,
333	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
334	                 "after 20s; launching the debugger anyway\n",
335	                 jtag_port.c_str());
336	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
337	  // localhost, port 9104) instead of its default real-hardware adapter; without
338	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
339	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
340	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
341	}
