113	// The engine whose hardware this plan's fast leg(s) must model: the plan's
114	// explicit hw_engine_id (the --verify oracle plan, which has no accurate leg
115	// of its own), else its first accurate-leg step's engine.
116	static const EngineDescriptor* plan_hw_engine(
117	    const Plan& plan, const std::vector<EngineDescriptor>& engines) {
118	  if (!plan.hw_engine_id.empty())
119	    return find_engine(engines, plan.hw_engine_id);
120	  for (const Step& s : plan.steps)
121	    if (s.role == "accurate-leg")
122	      return find_engine(engines, s.engine_id);
123	  return nullptr;
124	}
