163	// Drain everything readable on `fd` into `buf`, delivering each completed
164	// '\n'-terminated line (newline stripped) to on_line. Returns false at EOF /
165	// error so the caller stops polling that stream.
166	bool pump_stream(int fd, int stream, std::string& buf,
167	                 const std::function<void(int, std::string_view)>& on_line) {
168	  char rb[4096];
169	  const ssize_t n = read(fd, rb, sizeof rb);
170	  if (n == 0) return false;          // EOF: child closed this stream
171	  if (n < 0) return errno == EINTR;  // transient -> keep; real error -> stop
172	  buf.append(rb, static_cast<size_t>(n));
173	  size_t nl;
174	  while ((nl = buf.find('\n')) != std::string::npos) {
175	    on_line(stream, std::string_view(buf.data(), nl));
176	    buf.erase(0, nl + 1);
177	  }
178	  return true;
179	}
