181	}  // namespace
182	
183	int run_line_filtered(
184	    const std::vector<std::string>& argv,
185	    const std::function<void(int, std::string_view)>& on_line) {
186	  if (argv.empty()) return -1;
187	
188	  int out_fds[2], err_fds[2];
189	  if (pipe(out_fds) != 0) return -1;
190	  if (pipe(err_fds) != 0) {
191	    close(out_fds[0]);
192	    close(out_fds[1]);
193	    return -1;
194	  }
195	
196	  pid_t pid = fork();
197	  if (pid < 0) {
198	    close(out_fds[0]);
199	    close(out_fds[1]);
200	    close(err_fds[0]);
201	    close(err_fds[1]);
202	    return -1;
203	  }
204	
205	  if (pid == 0) {  // child: stdout/stderr to the pipes, stdin inherited
206	    close(out_fds[0]);
207	    close(err_fds[0]);
208	    dup2(out_fds[1], STDOUT_FILENO);
209	    dup2(err_fds[1], STDERR_FILENO);
210	    if (out_fds[1] > 2) close(out_fds[1]);
211	    if (err_fds[1] > 2) close(err_fds[1]);
212	    exec_or_die(argv);
213	  }
214	
215	  // parent: poll both pipes, line-buffer each, until both hit EOF. No timeout --
216	  // matches exec_passthrough (a cycle run can be arbitrarily long). The stream id
217	  // is index+1 (0 -> stdout=1, 1 -> stderr=2); a closed stream's fd is set to -1,
218	  // which poll() ignores (revents 0).
219	  close(out_fds[1]);
220	  close(err_fds[1]);
221	  const int fd[2] = {out_fds[0], err_fds[0]};
222	  std::string buf[2];
223	  bool open_[2] = {true, true};
224	
225	  struct pollfd pfd[2] = {{fd[0], POLLIN, 0}, {fd[1], POLLIN, 0}};
226	  while (open_[0] || open_[1]) {
227	    for (int i = 0; i < 2; ++i) pfd[i].fd = open_[i] ? fd[i] : -1;
228	    if (poll(pfd, 2, -1) < 0) {
229	      if (errno == EINTR) continue;
230	      break;
231	    }
232	    for (int i = 0; i < 2; ++i)
233	      if (open_[i] && (pfd[i].revents & (POLLIN | POLLHUP | POLLERR)))
234	        if (!pump_stream(fd[i], i + 1, buf[i], on_line)) open_[i] = false;
235	  }
236	  // Flush any final line that arrived without a trailing newline.
237	  for (int i = 0; i < 2; ++i)
238	    if (!buf[i].empty()) on_line(i + 1, buf[i]);
239	
240	  close(fd[0]);
241	  close(fd[1]);
242	  return wait_for_exit_code(pid);
243	}
