137	MmapDirChoice resolve_mmap_dir(
138	    const std::vector<MmapTier>& tiers, long long size,
139	    const std::function<long long(const std::string&)>& probe,
140	    std::string& err) {
141	  const long long need = size + kMmapSafetyMargin;
142	  std::vector<std::string> reasons;
143	  for (const MmapTier& t : tiers) {
144	    const long long free = probe(t.dir);
145	    if (free >= need) {
146	      err.clear();
147	      std::string note;
148	      for (size_t i = 0; i < reasons.size(); i++)
149	        note += (i ? "; " : "") + reasons[i];
150	      return {t.dir, note};
151	    }
152	    reasons.push_back(free < 0 ? t.label + " missing"
153	                               : t.label + " too small (" +
154	                                     format_bytes(free) + " free)");
155	  }
156	  err = "no mmap directory can hold " + format_bytes(size) +
157	        " + 256 MiB margin: ";
158	  for (size_t i = 0; i < reasons.size(); i++)
159	    err += (i ? "; " : "") + reasons[i];
160	  err += "; set HSIM_MMAP_DIR to a directory with enough free space";
161	  return {"", ""};
162	}
