187	std::string allocate(long long size, std::string& err,
188	                     const std::string& prefix) {
189	  const MmapDirChoice choice =
190	      resolve_mmap_dir(mmap_tiers(), size, free_bytes, err);
191	  if (choice.dir.empty()) return "";
192	
193	  std::string tmpl = choice.dir + "/" + prefix + "XXXXXX";
194	  std::vector<char> buf(tmpl.begin(), tmpl.end());
195	  buf.push_back('\0');
196	  const int fd = mkstemp(buf.data());
197	  if (fd < 0) {
198	    err = "failed to create mmap file in " + choice.dir;
199	    return "";
200	  }
201	  close(fd);
202	  const std::string path(buf.data());
203	  if (truncate(path.c_str(), size) != 0) {
204	    unlink(path.c_str());
205	    err = "failed to size mmap file " + path;
206	    return "";
207	  }
208	
209	  std::string line = "[andesim] mmap " + format_bytes(size) + " at " +
210	                     choice.dir + " (free: " + format_bytes(free_bytes(choice.dir)) + ")";
211	  if (!choice.note.empty()) line += " (fallback: " + choice.note + ")";
212	  log_line(kLogDebug, "%s", line.c_str());
213	  err.clear();
214	  return path;
215	}
