12	// AE350 platform constants shared by BOTH engines (QEMU andes_ae350.c memmap
13	// table; vsim src/platform/memory_map.h). The print-memmap contract test
14	// cross-checks these against the engine's own dump.
15	constexpr uint64_t kSimControlBase = 0xe0080000;
16	constexpr uint64_t kSimControlSize = 0x1000;
17	constexpr uint64_t kUart2Base = 0xf0300000;
18	constexpr uint64_t kUart2Size = 0x100000;
19	
20	// Strip one trailing '\r' (the cfg may come from a CRLF-writing engine) and
21	// surrounding spaces/tabs.
22	std::string trim(const std::string& s) {
23	  size_t b = s.find_first_not_of(" \t\r");
24	  if (b == std::string::npos) return "";
25	  size_t e = s.find_last_not_of(" \t\r");
26	  return s.substr(b, e - b + 1);
27	}
28	
29	// `key = "value"` -> value (quotes optional); "" when the line is not `key = ...`.
30	std::string ini_value(const std::string& line, const char* key) {
31	  const std::string t = trim(line);
32	  const std::string pfx = std::string(key);
33	  if (t.compare(0, pfx.size(), pfx) != 0) return "";
34	  size_t i = pfx.size();
35	  while (i < t.size() && (t[i] == ' ' || t[i] == '\t')) ++i;
36	  if (i >= t.size() || t[i] != '=') return "";
37	  ++i;
38	  while (i < t.size() && (t[i] == ' ' || t[i] == '\t')) ++i;
39	  std::string v = t.substr(i);
40	  if (v.size() >= 2 && v.front() == '"' && v.back() == '"')
41	    v = v.substr(1, v.size() - 2);
42	  return v;
43	}
44	
45	}  // namespace
46	
47	std::map<std::string, std::string> qemu_cfg_soc_props(
48	    const std::string& cfg_text) {
49	  std::map<std::string, std::string> out;
50	  // Each [global] block carries driver/property/value lines (any order per
51	  // QEMU's -readconfig grammar; the engine emits driver first). Collect the
52	  // triple per block; commit it when the block ends or the text does.
53	  std::string drv, prop, val;
54	  bool have_val = false;
55	  auto commit = [&] {
56	    if (drv == "riscv.andes.ae350.soc" && !prop.empty() && have_val)
57	      out[prop] = val;
58	    drv.clear();
59	    prop.clear();
60	    val.clear();
61	    have_val = false;
62	  };
63	  size_t pos = 0;
64	  while (pos <= cfg_text.size()) {
65	    const size_t nl = cfg_text.find('\n', pos);
66	    const std::string line =
67	        cfg_text.substr(pos, nl == std::string::npos ? nl : nl - pos);
68	    const std::string t = trim(line);
69	    if (t == "[global]") {
70	      commit();
71	    } else if (std::string v = ini_value(line, "driver"); !v.empty()) {
72	      drv = v;
73	    } else if (std::string v = ini_value(line, "property"); !v.empty()) {
74	      prop = v;
75	    } else if (std::string v = ini_value(line, "value"); !v.empty()) {
76	      val = v;
77	      have_val = true;
78	    }
79	    if (nl == std::string::npos) break;
80	    pos = nl + 1;
81	  }
82	  commit();
83	  return out;
84	}
