86	MemmapResult hybrid_memmap(const EngineDescriptor& eng, long long mem_size,
87	                           const std::string& qemu_cfg_text) {
88	  MemmapResult r;
89	  const uint64_t mem = static_cast<uint64_t>(mem_size);
90	
91	  r.rows.push_back({"DRAM", 0, mem - 1,
92	                    "shared mmap; content survives the handoff"});
93	  r.rows.push_back({"V-scratch", mem, mem + HYBRID_V_SCRATCH_BYTES - 1,
94	                    "reserved by the hybrid V transport; not program-usable"});
95	
96	  const auto props = qemu_cfg_soc_props(qemu_cfg_text);
97	  // ilm/dlm/hvm rows need BOTH a transportable size (descriptor, backdoor-
98	  // gated) AND the base from the engine's cfg. Sizes come from the descriptor:
99	  // they are the bytes the sidecar actually carries.
100	  auto base_of = [&](const char* key) -> const std::string* {
101	    auto it = props.find(key);
102	    return it == props.end() ? nullptr : &it->second;
103	  };
104	  bool geometry_missing = false;
105	  auto lm_row = [&](const char* region, const char* base_key, long size,
106	                    const std::string& transport) {
107	    if (size <= 0) return;  // engine cannot transport it -> unsupported -> omit
108	    const std::string* b = base_of(base_key);
109	    if (!b) {
110	      geometry_missing = true;
111	      return;
112	    }
113	    const uint64_t base = std::strtoull(b->c_str(), nullptr, 0);
114	    r.rows.push_back(
115	        {region, base, base + static_cast<uint64_t>(size) - 1, transport});
116	  };
117	  lm_row("ILM", "ilm_base", eng.ilm_size,
118	         "sidecar .ilm; DRAM overlay while milmb.IEN=1");
119	  lm_row("DLM", "dlm_base", eng.dlm_size,
120	         "sidecar .dlm; DRAM overlay while mdlmb.IEN=1");
121	  lm_row("HVM", "hvm_base", eng.hvm_size, "sidecar .hvm");
122	  if (geometry_missing)
123	    r.warnings.push_back(
124	        "engine '" + eng.id +
125	        "' reports transportable local memories but its --print-qemu-config "
126	        "gave no geometry; ILM/DLM/HVM rows omitted");
127	
128	  r.rows.push_back({"SimControl/HTIF", kSimControlBase,
129	                    kSimControlBase + kSimControlSize - 1,
130	                    "device; state does not cross the handoff"});
131	  r.rows.push_back({"UART2", kUart2Base, kUart2Base + kUart2Size - 1,
132	                    "device (console); state does not cross the handoff"});
133	  return r;
134	}
135	
136	std::string fmt_size(uint64_t bytes) {
137	  constexpr uint64_t kK = 1024, kM = kK * 1024, kG = kM * 1024;
138	  char buf[32];
139	  if (bytes >= kG && bytes % kG == 0)
140	    std::snprintf(buf, sizeof buf, "%lluG",
141	                  static_cast<unsigned long long>(bytes / kG));
142	  else if (bytes >= kM && bytes % kM == 0)
143	    std::snprintf(buf, sizeof buf, "%lluM",
144	                  static_cast<unsigned long long>(bytes / kM));
145	  else if (bytes >= kK && bytes % kK == 0)
146	    std::snprintf(buf, sizeof buf, "%lluK",
147	                  static_cast<unsigned long long>(bytes / kK));
148	  else
149	    std::snprintf(buf, sizeof buf, "%llu",
150	                  static_cast<unsigned long long>(bytes));
151	  return buf;
152	}
153	
154	std::string render_memmap(const MemmapResult& r) {
155	  // Fixed-width columns sized for 64-bit hex; END is the INCLUSIVE last byte.
156	  std::string out;
157	  char line[256];
158	  std::snprintf(line, sizeof line, "%-16s %-12s %-12s %-7s %s\n", "REGION",
159	                "BASE", "END", "SIZE", "TRANSPORT");
160	  out += line;
161	  for (const MemmapRow& row : r.rows) {
162	    char base[24], end[24];
163	    std::snprintf(base, sizeof base, "0x%llx",
164	                  static_cast<unsigned long long>(row.base));
165	    std::snprintf(end, sizeof end, "0x%llx",
166	                  static_cast<unsigned long long>(row.end));
167	    std::snprintf(line, sizeof line, "%-16s %-12s %-12s %-7s %s\n",
168	                  row.region.c_str(), base, end,
169	                  fmt_size(row.end - row.base + 1).c_str(),
170	                  row.transport.c_str());
171	    out += line;
172	  }
173	  for (const std::string& w : r.warnings) out += "warning: " + w + "\n";
174	  return out;
175	}
