18	// POSIX shell-quote one arg so a rendered command line is copy-pasteable. A
19	// token of only safe characters passes through; anything else (empty, spaces,
20	// quotes, globs) is wrapped in single quotes with embedded `'` escaped as
21	// '\''. Used by render_argv for the --dry-run command preview.
22	inline std::string shell_quote(const std::string& s) {
23	  if (!s.empty()) {
24	    bool safe = true;
25	    for (char c : s)
26	      if (!std::isalnum(static_cast<unsigned char>(c)) &&
27	          !std::strchr("_@%+=:,./-", c)) {
28	        safe = false;
29	        break;
30	      }
31	    if (safe) return s;
32	  }
33	  std::string out = "'";
34	  for (char c : s) out += (c == '\'') ? "'\\''" : std::string(1, c);
35	  out += "'";
36	  return out;
37	}
38	
39	// Join an argv into one shell-quoted line (each token via shell_quote).
40	inline std::string render_argv(const std::vector<std::string>& argv) {
41	  std::string out;
42	  for (size_t i = 0; i < argv.size(); ++i) {
43	    if (i) out += ' ';
44	    out += shell_quote(argv[i]);
45	  }
46	  return out;
47	}
48	
49	// Print the dry-run preview: the exact command(s) andesim WOULD spawn, each
50	// shell-quoted and labeled, executing nothing. Shared by run and profile so
51	// the preview format is identical; `labels[i]` annotates `argvs[i]` (e.g.
52	// "standalone [qemu64]", "profile [vsim:x]"). Always returns 0 -- a dry run
53	// reports the plan, it does not run it.
54	inline int print_dry_run(const std::vector<std::vector<std::string>>& argvs,
55	                         const std::vector<std::string>& labels) {
56	  std::printf("[andesim] dry-run: %zu command(s), not executed\n", argvs.size());
57	  for (size_t i = 0; i < argvs.size(); ++i) {
58	    std::printf("# command %zu/%zu: %s\n", i + 1, argvs.size(),
59	                labels[i].c_str());
60	    std::printf("%s\n", render_argv(argvs[i]).c_str());
61	  }
62	  return 0;
63	}
64	
65	// Substitute every "{key}" in `tmpl`'s args with `ctx.at(key)`. A key may
66	// appear anywhere in an arg (so "mem-path={mmap},size={mmap_size}" expands in
67	// one arg) and more than once. Recognised keys come from `ctx`; a "{key}" with
68	// no matching ctx entry is an error (returns {} and sets `err`). On success
69	// `err` is cleared and the fully-resolved argv is returned.
70	std::vector<std::string> build_argv(const std::vector<std::string>& tmpl,
71	                                    const std::map<std::string, std::string>& ctx,
72	                                    std::string& err);
73	
74	}  // namespace andes_sim
