9	namespace andes_sim {
10	namespace {
11	
12	// Numeric value of a bare-hex PC string from resolve_pc. resolve_pc already
13	// validated the digits; an absurd >64-bit address (out_of_range) yields false,
14	// so the equal-ROI guard simply skips it (the bogus address fails downstream).
15	bool hex_pc(const std::string& s, uint64_t& out) {
16	  try {
17	    std::size_t pos = 0;
18	    out = std::stoull(s, &pos, 16);
19	    return pos == s.size();
20	  } catch (...) {
21	    return false;
22	  }
23	}
24	
25	}  // namespace
26	
27	Trigger hybrid_trigger(const Cli& cli, const std::string& elf,
28	                       std::string& err) {
29	  err.clear();
30	  // --trigger is REQUIRED for hybrid: no silent default. An absent trigger used
31	  // to fall back to marker, which masked running an unmarked ELF (the fast leg
32	  // ran to completion instead of draining at the ROI, surfacing only as a
33	  // cryptic "expected exit 200, got 0"). Make the user name the ROI delimiter.
34	  if (cli.trigger.empty()) {
35	    err = "--trigger marker|pc is required "
36	          "(the ROI delimiter; see 'andesim run --help')";
37	    return {};
38	  }
39	  const std::string kind = cli.trigger;
40	
41	  if (kind == "marker") return {"marker", {}};  // markers in the workload; no params
42	
43	  if (kind == "pc") {
44	    if (cli.pc_start.empty() || cli.pc_end.empty()) {
45	      err = "trigger pc requires --pc-start and --pc-end "
46	            "(a symbol name or 0x address)";
47	      return {};
48	    }
49	    std::string e1, e2;
50	    const std::string enter = resolve_pc(elf, cli.pc_start, e1);
51	    if (!e1.empty()) { err = e1; return {}; }
52	    const std::string exit = resolve_pc(elf, cli.pc_end, e2);
53	    if (!e2.empty()) { err = e2; return {}; }
54	    // A zero-length ROI (enter == exit) is degenerate: vsim resumes at the
55	    // enter PC and the exit trigger fires on that very instruction, so the
56	    // window measures nothing. Compare numerically -- a symbol and its literal
57	    // 0x address (or 0x0001000 vs 0x1000) are different strings, same PC.
58	    uint64_t a_enter = 0, a_exit = 0;
59	    if (hex_pc(enter, a_enter) && hex_pc(exit, a_exit) && a_enter == a_exit) {
60	      err = "trigger pc: --pc-start and --pc-end resolve to the same address "
61	            "0x" + enter + " (an empty ROI measures nothing)";
62	      return {};
63	    }
64	    // L3 decision log: what the user's boundary specs resolved to.
65	    log_line(kLogDebug, "[andesim] trigger pc: %s -> 0x%s, %s -> 0x%s",
66	             cli.pc_start.c_str(), enter.c_str(), cli.pc_end.c_str(),
67	             exit.c_str());
68	    // Store with the 0x prefix the plugin (enter_pc=0x..) and vsim
69	    // (--hybrid-exit-pc 0x..) expect; leg_trigger_args concatenates verbatim.
70	    return {"pc", {{"enter_pc", "0x" + enter}, {"exit_pc", "0x" + exit}}};
71	  }
72	
73	  err = "unknown trigger '" + kind + "' (want marker|pc)";
74	  return {};
75	}
