77	std::string hybrid_hw_check(const EngineDescriptor& acc) {
78	  if (acc.xlen != 0 && acc.xlen != 64)
79	    return "engine " + acc.id + " is rv" + std::to_string(acc.xlen) +
80	           " (xlen=" + std::to_string(acc.xlen) +
81	           "); the hybrid fast leg (QEMU) is rv64-only";
82	  return "";
83	}
