27	// builtin_qemu_arch, the hybrid plan steps, and `run --mode fast` acceptance all
28	// agree -- a renamed literal would otherwise break find_engine() lookups only at
29	// run time.
30	inline constexpr const char* kQemuId64 = "qemu64";
31	inline constexpr const char* kQemuId32 = "qemu32";
