41	// is unset: VSIM_BIN_DIR (the external prebuilt vsim build, mirroring
42	// QEMU_BIN_DIR) resolved env-first then from `config_file` (default: the repo
43	// config.env); empty when unset everywhere.
44	std::filesystem::path vsim_scan_dir();
