1	// Reader for a drained hybrid_state_v1 file. Header-only:
2	// it #includes the shared ABI directly, so mcycle/minstret/flags/vlenb are
3	// struct members with no hand-copied offsets.
4	#ifndef ANDESIM_STATE_HPP
5	#define ANDESIM_STATE_HPP
6	
7	#include <cstdio>
8	#include <vector>
9	#include <string>
10	
11	#include "hybrid/state_abi.h"
12	
13	namespace andes_sim {
14	
15	struct StateFile {
16	  hybrid_state_v1 st{};
17	  std::string error;  // empty => valid; non-empty describes the rejection
18	  bool ok() const { return error.empty(); }
19	};
20	
21	// Read `path` and validate it (in order): byte size == sizeof(hybrid_state_v1),
22	// magic == HYBRID_STATE_MAGIC, version == HYBRID_STATE_VERSION. On any failure
23	// `error` is set and `st` is unspecified; otherwise `st` holds the full state.
24	inline StateFile read_state_file(const std::string& path) {
25	  StateFile r;
26	  std::FILE* f = std::fopen(path.c_str(), "rb");
27	  if (!f) {
28	    r.error = path + ": cannot open";
29	    return r;
30	  }
31	  std::fseek(f, 0, SEEK_END);
32	  const long sz = std::ftell(f);
33	  std::rewind(f);
34	  if (sz != static_cast<long>(sizeof(hybrid_state_v1))) {
35	    r.error = path + ": size " + std::to_string(sz) + " != expected " +
36	              std::to_string(sizeof(hybrid_state_v1));
37	    std::fclose(f);
38	    return r;
39	  }
40	  const size_t n = std::fread(&r.st, 1, sizeof(r.st), f);
41	  std::fclose(f);
42	  if (n != sizeof(r.st)) {
43	    r.error = path + ": short read";
44	    return r;
45	  }
46	
47	  char buf[256];
48	  if (r.st.magic != HYBRID_STATE_MAGIC) {
49	    std::snprintf(buf, sizeof(buf), "%s: magic 0x%08x != expected 0x%08x",
50	                  path.c_str(), r.st.magic, HYBRID_STATE_MAGIC);
51	    r.error = buf;
52	    return r;
53	  }
54	  if (r.st.version != HYBRID_STATE_VERSION) {
55	    std::snprintf(buf, sizeof(buf), "%s: version %u != expected %u",
56	                  path.c_str(), r.st.version, HYBRID_STATE_VERSION);
57	    r.error = buf;
58	    return r;
59	  }
60	  return r;
61	}
62	
63	}  // namespace andes_sim
64	
65	#endif  // ANDESIM_STATE_HPP
